import random

def estimar_pi(n):
    dentro = 0
    for _ in range(n):
        x = random.uniform(-1, 1)
        y = random.uniform(-1, 1)
        if x*x + y*y <= 1:
            dentro += 1
    return 4 * dentro / n

random.seed(42)
for n in [100, 1000, 10000, 100000]:
    print(f"n={n}: {estimar_pi(n):.5f}")

import time

def biseccion(f, a, b, tol=1e-10):
    for _ in range(100):
        c = (a + b) / 2
        if (b - a) / 2 < tol:
            return c
        if f(a) * f(c) < 0:
            b = c
        else:
            a = c
    return c

def newton(f, df, x0, tol=1e-10):
    x = x0
    for _ in range(100):
        x_nuevo = x - f(x) / df(x)
        if abs(x_nuevo - x) < tol:
            return x_nuevo
        x = x_nuevo
    return x

f = lambda x: x**3 - x - 1
df = lambda x: 3*x**2 - 1

t0 = time.perf_counter()
for _ in range(1000):
    biseccion(f, 1, 2)
t1 = time.perf_counter()
print(f"Bisección: {(t1-t0)*1000:.2f} ms")

t0 = time.perf_counter()
for _ in range(1000):
    newton(f, df, 1.5)
t1 = time.perf_counter()
print(f"Newton:    {(t1-t0)*1000:.2f} ms")
